import { invoke } from "@tauri-apps/api/core";
import { listen } from "@tauri-apps/api/event";

// Typed bridge to the Rust core. In a later pass this is generated by tauri-specta; hand-written now.

export interface ProviderInfo {
  id: string;
  display_name: string;
  available: boolean;
  needs_node: boolean;
}

export interface SkillInfo {
  id: string;
  name: string;
  description: string;
  icon: string | null;
  kind: string;
}

export interface SessionInfo {
  id: string;
  title: string;
  provider: string | { custom: string };
  model: string | null;
  cwd: string;
  worktree_path: string | null;
  permission_mode: string;
  acp_session_id: string | null;
  created_at: number;
}

/// Neutral document shape the editor serializes into; matches core `DocBlock` serde.
export type DocBlock =
  | { type: "text"; text: string }
  | { type: "skill"; skill_id: string; params: Record<string, string> };

/// Mirrors core `Event` (tagged by `event`, snake_case).
export type CoreEvent =
  | { event: "session_created"; session: string }
  | { event: "agent_text"; session: string; message_id: string; text: string }
  | { event: "agent_thought"; session: string; text: string }
  | { event: "tool_call"; session: string; id: string; title: string; status: string }
  | { event: "plan"; session: string; entries: string[] }
  | { event: "permission_request"; session: string; request_id: string; title: string; options: [string, string][] }
  | { event: "usage"; session: string; input_tokens: number; output_tokens: number }
  | { event: "turn_ended"; session: string; stop_reason: string }
  | { event: "error"; session: string | null; message: string };

export interface PtyOutput {
  id: number;
  data: string;
}

/// Mirrors core `Part` (tagged by `kind`).
export type Part =
  | { kind: "text"; text: string }
  | { kind: "reasoning"; text: string }
  | { kind: "tool_call"; id: string; title: string; status: string }
  | { kind: "plan"; entries: string[] };

export type TranscriptEntry = [string, Part]; // [role, part]

export type SkillPayload =
  | { kind: "fragment"; text: string }
  | { kind: "macro"; template: string; slots: string[] };

export interface Skill {
  id: string;
  name: string;
  description: string;
  icon: string | null;
  payload: SkillPayload;
}

// True only inside the Tauri webview; lets `vite build`/`preview` run in a plain browser.
const inTauri = typeof (globalThis as { __TAURI_INTERNALS__?: unknown }).__TAURI_INTERNALS__ !== "undefined";

const FALLBACK_PROVIDERS: ProviderInfo[] = [
  { id: "claude_code", display_name: "Claude Code", available: false, needs_node: true },
  { id: "codex", display_name: "OpenAI Codex", available: false, needs_node: true },
  { id: "grok", display_name: "Grok", available: false, needs_node: false },
  { id: "cursor", display_name: "Cursor", available: false, needs_node: false },
  { id: "opencode", display_name: "OpenCode", available: false, needs_node: false },
];

const FALLBACK_SKILLS: SkillInfo[] = [
  { id: "reviewer", name: "Code Reviewer", description: "Meticulous reviewer", icon: "🔍", kind: "fragment" },
  { id: "test-writer", name: "Test Writer", description: "Thorough tests", icon: "🧪", kind: "fragment" },
  { id: "security-audit", name: "Security Audit", description: "Find vulns", icon: "🛡️", kind: "fragment" },
  { id: "commit-macro", name: "Commit Message", description: "Commit macro", icon: "📝", kind: "macro" },
];

export async function listProviders(): Promise<ProviderInfo[]> {
  return inTauri ? invoke<ProviderInfo[]>("list_providers") : FALLBACK_PROVIDERS;
}

export async function listSkills(): Promise<SkillInfo[]> {
  return inTauri ? invoke<SkillInfo[]>("list_skills") : FALLBACK_SKILLS;
}

export async function listSessions(): Promise<SessionInfo[]> {
  return inTauri ? invoke<SessionInfo[]>("list_sessions") : [];
}

export async function newSession(provider: string, cwd: string, useWorktree: boolean): Promise<void> {
  if (inTauri) await invoke("new_session", { provider, cwd, useWorktree });
}

export async function submitPrompt(session: string, doc: DocBlock[]): Promise<void> {
  if (inTauri) await invoke("submit_prompt", { session, doc });
}

export async function answerPermission(session: string, requestId: string, optionId: string | null): Promise<void> {
  if (inTauri) await invoke("answer_permission", { session, requestId, optionId });
}

export async function setPermissionMode(session: string, mode: string): Promise<void> {
  if (inTauri) await invoke("set_permission_mode", { session, mode });
}

export async function cancelTurn(session: string): Promise<void> {
  if (inTauri) await invoke("cancel_turn", { session });
}

export async function ptySpawn(id: number, cwd: string | null, rows: number, cols: number): Promise<void> {
  if (inTauri) await invoke("pty_spawn", { id, cwd, rows, cols });
}

export async function ptyWrite(id: number, data: string): Promise<void> {
  if (inTauri) await invoke("pty_write", { id, data });
}

export async function ptyResize(id: number, rows: number, cols: number): Promise<void> {
  if (inTauri) await invoke("pty_resize", { id, rows, cols });
}

export async function getTranscript(session: string): Promise<TranscriptEntry[]> {
  return inTauri ? invoke<TranscriptEntry[]>("get_transcript", { session }) : [];
}

// ---- git (F1) --------------------------------------------------------------------------------

export interface GitFile {
  path: string;
  staged: boolean;
  state: string;
}
export interface GitStatus {
  is_repo: boolean;
  branch: string;
  ahead: number;
  behind: number;
  files: GitFile[];
}

export async function gitStatus(cwd: string): Promise<GitStatus> {
  return inTauri
    ? invoke<GitStatus>("git_status", { cwd })
    : { is_repo: false, branch: "", ahead: 0, behind: 0, files: [] };
}

export interface Checkpoint {
  id: string;
  refname: string;
  commit: string;
  message: string;
}

export async function gitCheckpoint(cwd: string, message: string): Promise<Checkpoint | null> {
  return inTauri ? invoke<Checkpoint>("git_checkpoint", { cwd, message }) : null;
}
export async function gitCheckpoints(cwd: string): Promise<Checkpoint[]> {
  return inTauri ? invoke<Checkpoint[]>("git_checkpoints", { cwd }) : [];
}
export async function gitDiff(cwd: string, path: string | null): Promise<string> {
  return inTauri ? invoke<string>("git_diff", { cwd, path }) : "";
}
export async function gitDiffSince(cwd: string, commit: string): Promise<string> {
  return inTauri ? invoke<string>("git_diff_since", { cwd, commit }) : "";
}
export async function gitRevert(cwd: string, commit: string): Promise<void> {
  if (inTauri) await invoke("git_revert", { cwd, commit });
}
export async function gitCommit(cwd: string, message: string): Promise<string> {
  return inTauri ? invoke<string>("git_commit", { cwd, message }) : "";
}
export async function gitPush(cwd: string): Promise<string> {
  return inTauri ? invoke<string>("git_push", { cwd }) : "";
}

